with valid as (select *, lower(status) as status_lower, concat(plan, ' - ', status) as plan_status from subscriptions where customer_id is not null), remaining_keys as (select customer_id, id from valid except select customer_id, id from subscriptions where end_date between '2023-10-01' and '2024-04-10'), reconciled as (select s.* from valid s inner join remaining_keys k on s.customer_id = k.customer_id and s.id = k.id), with_dims as (select a.*, c.credit_limit, c.email from reconciled a left join customers c on a.customer_id = c.id where c.country = 'UK'), enriched as (select e.id, e.customer_id, e.plan, e.status, e.status_lower, e.email, d.city, d.name from with_dims e inner join customers d on e.customer_id <=> d.id) select city, count(*) as event_count, count(*) as row_count, size(collect_set(plan)) as num_plans, count_if(status = 'EXPIRED') as expired_events, sort_array(collect_set(plan)) as plan_list, sort_array(collect_set(plan)) as plan_list_2 from enriched group by city order by row_count desc nulls last;
